function fileDownload(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=el('a',{href:url,download:name});a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function message(text){const target=$('project-message');if(target)target.textContent=text;}
function loadProject(candidate){if(!valid(candidate))throw Error('Invalid project. Check dimensions, quantities and settings.');state=candidate;state.name=String(state.name||'Untitled job').slice(0,120);renderInputs();changed();run();}
function csvRows(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(!quoted&&(c===','||c==='\r'||c==='\n')){row.push(cell);cell='';if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(v=>v.trim()))rows.push(row);row=[];}}else cell+=c;}if(quoted)throw Error('CSV has an unclosed quote.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function parsePartsCSV(text){const rows=csvRows(text.replace(/^\uFEFF/,''));if(!rows.length||rows.shift().map(v=>v.trim().toLowerCase()).join(',')!=='label,width_cm,height_cm,quantity')throw Error('Use headers: label,width_cm,height_cm,quantity');const parts=rows.map((r,i)=>{if(r.length!==4)throw Error('CSV row '+(i+2)+' needs four columns.');return {label:r[0],w:Number(r[1]),h:Number(r[2]),qty:Number(r[3])};});if(!valid({...state,parts}))throw Error('Use positive dimensions and whole quantities; maximum 200 rows and 1,000 pieces.');return parts;}
const details=el('section',{id:'workshop-details',class:'panel'});$('legend').after(details);
function workshopDetails(){details.replaceChildren();const s=result?.sheets[selected];if(!s)return;details.append(el('h2',{},'Reusable offcuts'));const offcuts=el('div',{class:'offcuts'});s.free.forEach((f,i)=>offcuts.append(el('span',{},(i+1)+'. '+dimension(f.w)+' × '+dimension(f.h)+' cm')));if(!s.free.length)offcuts.append(el('span',{},'No reusable offcuts.'));details.append(offcuts);}
const baseDraw=draw;draw=function(){baseDraw();workshopDetails();};workshopDetails();
const originalReport=buildReport;buildReport=function(){originalReport();const report=$('print-report'),first=report.querySelector('.report-summary');if(first)first.prepend(el('h2',{},state.name||'Workshop project'));if(result.unplaced.length){const page=el('section',{class:'report-page'});page.append(el('h2',{},'Unplaced parts — not included in cutting layouts'),el('p',{},result.unplaced.length+' pieces need revised dimensions, orientation or stock.'));const summary=new Map();result.unplaced.forEach(p=>{const key=p.groupId;if(!summary.has(key))summary.set(key,{...p,count:0});summary.get(key).count++;});summary.forEach(p=>page.append(el('p',{},p.label+' · '+dimension(p.w)+' × '+dimension(p.h)+' cm · Qty '+p.count)));report.append(page);}};
